def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "broadcast_recorded_phrases": And([
            self.robot_at(self.private_discussion_area),
            self.recorded_phrases_loaded,  
            self.family_arguing,  
            self.sensing_private_argument,  
            self.robot_assigned 
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
